(5092259, 743675, 34938, '<td valign="top">DrAchoo? I cannot fault this and now give my first 10 in this challenge</td>', 'DrAchoo? I cannot fault this and now give my first 10 in this challenge', '2008-12-01 00:11:00.000000', NULL, 1),
(5092260, 743617, 70000, '<td valign="top">This photo is so insanely busy and totally awesome. Very cool modernization. I love the dance between all the people in the scene except for the woman in the black dress, feel like the flow would have been better if she had been crouching down lower and if the stretcher wasn''t there. Either way, very daring piece.</td>', 'This photo is so insanely busy and totally awesome. Very cool modernization. I love the dance between all the people in the scene except for the woman in the black dress, feel like the flow would have been better if she had been crouching down lower and if the stretcher wasn''t there. Either way, very daring piece.', '2008-12-01 00:11:07.000000', NULL, 1),
(5092261, 739513, 34938, '<td valign="top">powerful sky</td>', 'powerful sky', '2008-12-01 00:11:12.000000', NULL, 1),
