INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5092913, 740662, 72068, '<td valign="top">Whilst I find smoking gross, this is just great photography.</td>', 'Whilst I find smoking gross, this is just great photography.', '2008-12-01 02:42:11.000000', NULL, 1),
(5092914, 737982, 72068, '<td valign="top">Their eyes tell a very sad story.</td>', 'Their eyes tell a very sad story.', '2008-12-01 02:42:30.000000', NULL, 1),
(5092917, 743249, 23430, '<td valign="top">Nice lighting. She looks very relaxed. Good work.</td>', 'Nice lighting. She looks very relaxed. Good work.', '2008-12-01 02:42:55.000000', NULL, 1),
(5092920, 742642, 72068, '<td valign="top">I love this :D</td>', 'I love this :D', '2008-12-01 02:43:29.000000', NULL, 1),
(5092925, 743191, 72068, '<td valign="top">Truly excellent capture, this is going to be a top scorer!</td>', 'Truly excellent capture, this is going to be a top scorer!', '2008-12-01 02:43:55.000000', NULL, 1),
(5092928, 743636, 72068, '<td valign="top">My flatmate loves this band, plays them so loud! <br/> <br/>Anyway, I love the symmetry of the lighting on the crowd, you did well to capture them at this moment, good stuff!</td>', 'My flatmate loves this band, plays them so loud!  Anyway, I love the symmetry of the lighting on the crowd, you did well to capture them at this moment, good stuff!', '2008-12-01 02:44:31.000000', NULL, 1),
(5092931, 739002, 72068, '<td valign="top">Lovely Macro.</td>', 'Lovely Macro.', '2008-12-01 02:45:09.000000', NULL, 1),
(5092933, 739882, 23430, '<td valign="top">Nice detail.</td>', 'Nice detail.', '2008-12-01 02:45:22.000000', NULL, 1),
(5092936, 736523, 72068, '<td valign="top">I''m shocked they even got that close.</td>', 'I''m shocked they even got that close.', '2008-12-01 02:46:10.000000', NULL, 1),
(5092938, 743749, 72068, '<td valign="top">Those ducks add so much to the picture, looks like a lovely place.</td>', 'Those ducks add so much to the picture, looks like a lovely place.', '2008-12-01 02:46:40.000000', NULL, 1),
(5092944, 742392, 23430, '<td valign="top">Awesome detail on the snail. The lighting is perfect and I don''t know how you got such a deep depth of field. Congrats.</td>', 'Awesome detail on the snail. The lighting is perfect and I don''t know how you got such a deep depth of field. Congrats.', '2008-12-01 02:48:29.000000', NULL, 1),
(5092960, 736918, 23430, '<td valign="top">Nice shot, the tones are excellent.</td>', 'Nice shot, the tones are excellent.', '2008-12-01 02:52:17.000000', NULL, 1),
(5092968, 743682, 23430, '<td valign="top">Beautiful shot. Stunning simplicity.</td>', 'Beautiful shot. Stunning simplicity.', '2008-12-01 02:54:17.000000', NULL, 1),
(5092978, 735858, 23430, '<td valign="top">I think I need new glasses :). Seriously though it''s a nice compostion and the blur is good. Like a fine painting.</td>', 'I think I need new glasses :). Seriously though it''s a nice compostion and the blur is good. Like a fine painting.', '2008-12-01 02:57:45.000000', NULL, 1),
(5092983, 740734, 23430, '<td valign="top">Bizarre. Very nice country side.</td>', 'Bizarre. Very nice country side.', '2008-12-01 02:59:05.000000', NULL, 1),
(5093018, 739636, 63633, '<td valign="top">Love the umbrella folded up by the base of the cross. Everyone''s gotta have a signature ;) Not that this one needed it, it has your name written all over it :) Fantastic!</td>', 'Love the umbrella folded up by the base of the cross. Everyone''s gotta have a signature ;) Not that this one needed it, it has your name written all over it :) Fantastic!', '2008-12-01 03:16:13.000000', NULL, 1),
(5093019, 743617, 63633, '<td valign="top">Another De Sousa masterpiece. Stunning. Are they lowering him by his piercings?<br/>Love the addition of the stretcher in your version. Nice touch.</td>', 'Another De Sousa masterpiece. Stunning. Are they lowering him by his piercings?Love the addition of the stretcher in your version. Nice touch.', '2008-12-01 03:16:21.000000', NULL, 1),
(5093021, 743675, 41337, '<td valign="top">You have a great camera/lens! Oh and I''m sure you''re pretty good too. :)</td>', 'You have a great camera/lens! Oh and I''m sure you''re pretty good too. :)', '2008-12-01 03:17:57.000000', NULL, 1),
(5093030, 739636, 41337, '<td valign="top">Great title and of course image. Good luck Coley.</td>', 'Great title and of course image. Good luck Coley.', '2008-12-01 03:21:03.000000', NULL, 1),
(5093033, 743570, 41337, '<td valign="top">Wonderful lighting and I dig the color. Good choice keeping the dripping water within the area of her skirt. I think if it had been extended it would have made it more of a distracting element rather than a supportive one.</td>', 'Wonderful lighting and I dig the color. Good choice keeping the dripping water within the area of her skirt. I think if it had been extended it would have made it more of a distracting element rather than a supportive one.', '2008-12-01 03:21:35.000000', NULL, 1),
(5093041, 743361, 63633, '<td valign="top">I find the catchlights very distracting, but a beautiful image nonetheless.</td>', 'I find the catchlights very distracting, but a beautiful image nonetheless.', '2008-12-01 03:25:50.000000', NULL, 1),
(5093048, 743766, 2780, '<td valign="top">I think the border spoils what is quite a nice photo. I do however think the processing could do with some more contrast to stop the colours looking so washed out.</td>', 'I think the border spoils what is quite a nice photo. I do however think the processing could do with some more contrast to stop the colours looking so washed out.', '2008-12-01 03:29:24.000000', NULL, 1),
(5093051, 739513, 2780, '<td valign="top">I think this looks a bit over-processed and over-sharpened, sorry.</td>', 'I think this looks a bit over-processed and over-sharpened, sorry.', '2008-12-01 03:30:18.000000', NULL, 1),
(5093056, 743291, 2780, '<td valign="top">This makes me feel quite uncomfortable... I''m not sure what it is about it but it''s a powerful photo.</td>', 'This makes me feel quite uncomfortable... I''m not sure what it is about it but it''s a powerful photo.', '2008-12-01 03:33:03.000000', NULL, 1),
(5093060, 743152, 2780, '<td valign="top">I think this a fantastic shot</td>', 'I think this a fantastic shot', '2008-12-01 03:34:07.000000', NULL, 1),
(5093076, 741866, 2780, '<td valign="top">Excellent lighting here, and effective use of selective desaturation to draw the eye (as if I wasn''t going to look there anyway!)</td>', 'Excellent lighting here, and effective use of selective desaturation to draw the eye (as if I wasn''t going to look there anyway!)', '2008-12-01 03:39:46.000000', NULL, 1),
(5093082, 743466, 2780, '<td valign="top">I love this. I think it''s the colour and the blocky graphic silhouettes mixed with very fine delicate detail. Excellent.</td>', 'I love this. I think it''s the colour and the blocky graphic silhouettes mixed with very fine delicate detail. Excellent.', '2008-12-01 03:40:56.000000', NULL, 1),
(5093092, 740915, 39110, '<td valign="top">Quality image</td>', 'Quality image', '2008-12-01 03:42:37.000000', NULL, 1),
(5093100, 735858, 2780, '<td valign="top">For some reason which I can''t explain, I really like this. 8</td>', 'For some reason which I can''t explain, I really like this. 8', '2008-12-01 03:46:29.000000', NULL, 1),
(5093104, 739220, 2780, '<td valign="top">Lovely colours and painting-like quality. 10</td>', 'Lovely colours and painting-like quality. 10', '2008-12-01 03:47:54.000000', NULL, 1),
(5093117, 741834, 93421, '<td valign="top">Brilliant capture and title!</td>', 'Brilliant capture and title!', '2008-12-01 03:56:04.000000', NULL, 1),
(5093128, 743720, 49109, '<td valign="top">very appropriate. too much noise, white balance is off. b/w might have worked better. overall just interesting enough to write a comment, but that''s mostly due to the title. 3</td>', 'very appropriate. too much noise, white balance is off. b/w might have worked better. overall just interesting enough to write a comment, but that''s mostly due to the title. 3', '2008-12-01 04:03:26.000000', NULL, 1),
(5093131, 743617, 31889, '<td valign="top">Winner!</td>', 'Winner!', '2008-12-01 04:04:48.000000', NULL, 1),
(5093132, 742637, 49109, '<td valign="top">interesting idea, well exposed. don''t like the greenish cast. had preferred the front figure to be included in full length</td>', 'interesting idea, well exposed. don''t like the greenish cast. had preferred the front figure to be included in full length', '2008-12-01 04:04:51.000000', NULL, 1),
(5093134, 736494, 49109, '<td valign="top">very well composed. don''t like the color scheme</td>', 'very well composed. don''t like the color scheme', '2008-12-01 04:05:35.000000', NULL, 1),
(5093137, 743600, 49109, '<td valign="top">nice DOF and color. a tad overexposed. composition is too centered</td>', 'nice DOF and color. a tad overexposed. composition is too centered', '2008-12-01 04:06:53.000000', NULL, 1),
(5093141, 735858, 22459, '<td valign="top">Brilliant image, an ambiguously captured delight.</td>', 'Brilliant image, an ambiguously captured delight.', '2008-12-01 04:17:26.000000', NULL, 1),
(5093147, 743152, 49109, '<td valign="top">Really like the concept here. Lighting is good, props are well chosen. I believe, the angle you took hurts the idea, a straighter approach with the focal plane parallel to the wall with the image had had more impact. Overall there''s a purplish cast, but not enough to look as if it was there on purpose. A tad too  much softening IMO.</td>', 'Really like the concept here. Lighting is good, props are well chosen. I believe, the angle you took hurts the idea, a straighter approach with the focal plane parallel to the wall with the image had had more impact. Overall there''s a purplish cast, but not enough to look as if it was there on purpose. A tad too  much softening IMO.', '2008-12-01 04:24:42.000000', NULL, 1),
(5093148, 743639, 22459, '<td valign="top">very artistic,love it.</td>', 'very artistic,love it.', '2008-12-01 04:24:45.000000', NULL, 1),
(5093149, 743445, 49109, '<td valign="top">nothing wrong here, but also not too much of interest</td>', 'nothing wrong here, but also not too much of interest', '2008-12-01 04:26:07.000000', NULL, 1),
(5093150, 741864, 27161, '<td valign="top">I hate photos of circuit boards.  I think that they are the most boring thing to shoot macro.  But the first thing I saw when I looked at this photo is cityscape.  10 for opening my world.</td>', 'I hate photos of circuit boards.  I think that they are the most boring thing to shoot macro.  But the first thing I saw when I looked at this photo is cityscape.  10 for opening my world.', '2008-12-01 04:26:35.000000', NULL, 1),
(5093151, 737660, 27161, '<td valign="top">The frogs alone make this photo an 8 in my book.  They look great.  I don''t think the glass adds too much to the composition.  I think you could use a better receptacle.  Still great job.</td>', 'The frogs alone make this photo an 8 in my book.  They look great.  I don''t think the glass adds too much to the composition.  I think you could use a better receptacle.  Still great job.', '2008-12-01 04:28:09.000000', NULL, 1),
(5093152, 740915, 27161, '<td valign="top">Awesome!</td>', 'Awesome!', '2008-12-01 04:28:29.000000', NULL, 1),
(5093154, 738553, 49109, '<td valign="top">too much sharpening and again softening/noise reduction let all the details disappear. serious discoloration on the beak from oversaturating the yellows. slight pink cast in the white feathers.</td>', 'too much sharpening and again softening/noise reduction let all the details disappear. serious discoloration on the beak from oversaturating the yellows. slight pink cast in the white feathers.', '2008-12-01 04:29:57.000000', NULL, 1),
(5093155, 743592, 49109, '<td valign="top">very good sharpness, but just way oversaturated. the angle is far from perfect.</td>', 'very good sharpness, but just way oversaturated. the angle is far from perfect.', '2008-12-01 04:31:24.000000', NULL, 1),
(5093156, 743054, 27161, '<td valign="top">A new idea for water drops.  Great job.</td>', 'A new idea for water drops.  Great job.', '2008-12-01 04:32:18.000000', NULL, 1),
(5093158, 743682, 49109, '<td valign="top">i think I have seen this lighthouse far too often, so this lacks of any wow-factor. technically well done, though</td>', 'i think I have seen this lighthouse far too often, so this lacks of any wow-factor. technically well done, though', '2008-12-01 04:33:13.000000', NULL, 1),
(5093160, 742897, 27161, '<td valign="top">Wow, I think I have a postcard with that shot.  Amazing capture.</td>', 'Wow, I think I have a postcard with that shot.  Amazing capture.', '2008-12-01 04:33:52.000000', NULL, 1),
(5093163, 743726, 49109, '<td valign="top">overall a bit muddy-looking. wish there was more contrast of any kind (color/luminance/focus) between foreground and background</td>', 'overall a bit muddy-looking. wish there was more contrast of any kind (color/luminance/focus) between foreground and background', '2008-12-01 04:34:44.000000', NULL, 1),
(5093164, 741561, 27161, '<td valign="top">Perfect portrait.</td>', 'Perfect portrait.', '2008-12-01 04:34:47.000000', NULL, 1),
(5093165, 743617, 21124, '<td valign="top">That is a really interesting piece of work.<br/>It seems to be mostly inspired by Rosso Fiorentino (Il Rosso), with perhaps a bit of Inspiration from Rubens for the position of Mary. Mary Magdalene as kissing the feet seems be be a free interpretation from the photographer/director.<br/>Now, what I am trying to understand is why Saint John, which is the person on the bottom right within Rosso Fiorentino''s painting, and from which your bottom right character seems to be partially inspired, is depicted as a woman there.<br/> <br/>It''s now about 15 minutes that I am looking at your work, so within a DPC voting session I''d say that this is a success.</td>', 'That is a really interesting piece of work.It seems to be mostly inspired by Rosso Fiorentino (Il Rosso), with perhaps a bit of Inspiration from Rubens for the position of Mary. Mary Magdalene as kissing the feet seems be be a free interpretation from the photographer/director.Now, what I am trying to understand is why Saint John, which is the person on the bottom right within Rosso Fiorentino''s painting, and from which your bottom right character seems to be partially inspired, is depicted as a woman there. It''s now about 15 minutes that I am looking at your work, so within a DPC voting session I''d say that this is a success.', '2008-12-01 04:34:57.000000', NULL, 1),
(5093166, 743578, 27161, '<td valign="top">10.</td>', '10.', '2008-12-01 04:35:05.000000', NULL, 1),
(5093167, 740474, 49109, '<td valign="top">looks like a snapshot to me, the toning can''t change that</td>', 'looks like a snapshot to me, the toning can''t change that', '2008-12-01 04:35:35.000000', NULL, 1),
(5093169, 740734, 27161, '<td valign="top">Ooooh...</td>', 'Ooooh...', '2008-12-01 04:36:47.000000', NULL, 1),
(5093170, 741010, 27161, '<td valign="top">He he he :P</td>', 'He he he :P', '2008-12-01 04:37:51.000000', NULL, 1),
(5093179, 743639, 8643, '<td valign="top">Well done - it made me smile!</td>', 'Well done - it made me smile!', '2008-12-01 04:43:09.000000', NULL, 1),
(5093181, 740734, 49109, '<td valign="top">man, this is one dirty sensor!<br/>Seriously, what appears to be a beautiful landscape is uglified by this mass of birds. I wonder if this is real or an overlay, it seems like there are only birds in the sky and none close to the ground</td>', 'man, this is one dirty sensor!Seriously, what appears to be a beautiful landscape is uglified by this mass of birds. I wonder if this is real or an overlay, it seems like there are only birds in the sky and none close to the ground', '2008-12-01 04:43:28.000000', NULL, 1),
(5093182, 743617, 27161, '<td valign="top">Holy sh*t. 10</td>', 'Holy sh*t. 10', '2008-12-01 04:43:40.000000', NULL, 1),
(5093184, 739963, 49109, '<td valign="top">good timing, bit the lighting is too harsh, a reflector had helped here</td>', 'good timing, bit the lighting is too harsh, a reflector had helped here', '2008-12-01 04:44:18.000000', NULL, 1),
(5093185, 743270, 8643, '<td valign="top">Lovely idea, maybe a tiny bit more DoF to capture her head in focus?</td>', 'Lovely idea, maybe a tiny bit more DoF to capture her head in focus?', '2008-12-01 04:44:28.000000', NULL, 1),
(5093187, 741564, 8643, '<td valign="top">Brilliant - this is much more difficult than it looks!  At least seagulls are fairly compliant subjects.</td>', 'Brilliant - this is much more difficult than it looks!  At least seagulls are fairly compliant subjects.', '2008-12-01 04:46:44.000000', NULL, 1),
(5093194, 740092, 27161, '<td valign="top">Those eyes look amazing.</td>', 'Those eyes look amazing.', '2008-12-01 04:51:53.000000', NULL, 1),
(5093204, 739968, 49109, '<td valign="top">oversharpened, but still beautiful. excellent b/w conversion</td>', 'oversharpened, but still beautiful. excellent b/w conversion', '2008-12-01 04:56:40.000000', NULL, 1),
(5093209, 742353, 49109, '<td valign="top">very well done again, but the large portion of purple kinda distracts. had preferred a tighter crop and a less centered composition.</td>', 'very well done again, but the large portion of purple kinda distracts. had preferred a tighter crop and a less centered composition.', '2008-12-01 04:58:50.000000', NULL, 1),
(5093216, 741030, 49109, '<td valign="top">looks like the inside of a laundry machine. well done.</td>', 'looks like the inside of a laundry machine. well done.', '2008-12-01 05:00:08.000000', NULL, 1),
