(5093227, 743578, 49109, '<td valign="top">not sure about his gesture, spread arms might have been more appropriate. little blur at his arms. other than that very well done</td>', 'not sure about his gesture, spread arms might have been more appropriate. little blur at his arms. other than that very well done', '2008-12-01 05:01:55.000000', NULL, 1),
(5093256, 741053, 8643, '<td valign="top">Superb image - love the big boot!  My highest rated image too.</td>', 'Superb image - love the big boot!  My highest rated image too.', '2008-12-01 05:11:28.000000', NULL, 1),
(5093279, 743617, 8643, '<td valign="top">This is an arresting image, the work of a master.  I am not a fan of religious images otherwise this would have scored a 10.</td>', 'This is an arresting image, the work of a master.  I am not a fan of religious images otherwise this would have scored a 10.', '2008-12-01 05:16:22.000000', NULL, 1),
