INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5095301, 742353, 24454, '<td valign="top">Breeeeee?????   I hope so because if it is -- another ribbon for my friend :)  If not -- then what a compliment!  This is magical.  Breathtaking, and only my 2nd 10.</td>', 'Breeeeee?????   I hope so because if it is -- another ribbon for my friend :)  If not -- then what a compliment!  This is magical.  Breathtaking, and only my 2nd 10.', '2008-12-01 17:26:47.000000', NULL, 1),
(5095406, 739487, 32767, '<td valign="top">I''ve been a little bugged by images that seem to have been overburned these days. I don''t get it. When I first learned to burn and went too far my images suffered from what now seems like something that''s become popular.</td>', 'I''ve been a little bugged by images that seem to have been overburned these days. I don''t get it. When I first learned to burn and went too far my images suffered from what now seems like something that''s become popular.', '2008-12-01 18:13:16.000000', NULL, 1),
(5095414, 743152, 32767, '<td valign="top">Nice idea but the execution seems pretty static.</td>', 'Nice idea but the execution seems pretty static.', '2008-12-01 18:15:51.000000', NULL, 1),
