INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5097536, 743222, 18655, '<td valign="top">Awesome shot! The half bodies in the background are a little distracting to me but I''m sure you didn''t have a choice.</td>', 'Awesome shot! The half bodies in the background are a little distracting to me but I''m sure you didn''t have a choice.', '2008-12-02 10:40:50.000000', NULL, 1),
(5097539, 738279, 18655, '<td valign="top">Fantastic! I love it!! Composition, color tones, angle and use of wide angle is all good. My first 10 so far.</td>', 'Fantastic! I love it!! Composition, color tones, angle and use of wide angle is all good. My first 10 so far.', '2008-12-02 10:44:12.000000', NULL, 1),
(5097543, 743654, 18655, '<td valign="top">Very convincing and genuine. Great shot!</td>', 'Very convincing and genuine. Great shot!', '2008-12-02 10:46:34.000000', NULL, 1),
(5097546, 740662, 18655, '<td valign="top">Good crop, nice subtle colors, very sharp. Didn''t really like it so much at first but keep going back looking at it. Bumped it up to a 7</td>', 'Good crop, nice subtle colors, very sharp. Didn''t really like it so much at first but keep going back looking at it. Bumped it up to a 7', '2008-12-02 10:49:08.000000', NULL, 1),
(5097547, 743755, 18655, '<td valign="top">Nice effect. Good use of wide angle</td>', 'Nice effect. Good use of wide angle', '2008-12-02 10:50:23.000000', NULL, 1),
(5097556, 740891, 18655, '<td valign="top">Beautiful model with a very interesting expression that makes me wonder what she is thinking. Good crop, nice with the subtle colors/contrast. Clothing/hood is very appropriate. Very nice! Hopefully it will be the cover on DPC for a week or so :)</td>', 'Beautiful model with a very interesting expression that makes me wonder what she is thinking. Good crop, nice with the subtle colors/contrast. Clothing/hood is very appropriate. Very nice! Hopefully it will be the cover on DPC for a week or so :)', '2008-12-02 10:53:51.000000', NULL, 1),
(5097558, 743303, 43774, '<td valign="top">I love the bright colours, the clouds and the reflections.</td>', 'I love the bright colours, the clouds and the reflections.', '2008-12-02 10:53:55.000000', NULL, 1),
(5097560, 738060, 43774, '<td valign="top">That splash of colour in the middle of an otherwise mostly B&amp;W image is icing on the cake! I love the patterns, the swirls, the point of view. This is my kind of photo.</td>', 'That splash of colour in the middle of an otherwise mostly B&W image is icing on the cake! I love the patterns, the swirls, the point of view. This is my kind of photo.', '2008-12-02 10:54:03.000000', NULL, 1),
(5097563, 743592, 43774, '<td valign="top">So bright I need sunglasses!! I love it.</td>', 'So bright I need sunglasses!! I love it.', '2008-12-02 10:54:20.000000', NULL, 1),
(5097565, 742353, 43774, '<td valign="top">I am guessing this is <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=57775" rel="nofollow" target="_blank">Breeee123</a>''s photo. It''s beautiful.</td>', 'I am guessing this is  Breeee123''s photo. It''s beautiful.', '2008-12-02 10:54:59.000000', NULL, 1),
(5097566, 738553, 43774, '<td valign="top">So clear, so sharp, what a fierce gaze.</td>', 'So clear, so sharp, what a fierce gaze.', '2008-12-02 10:55:13.000000', NULL, 1),
