(5102153, 739931, 39427, '<td valign="top">I like the moving snow flakes, that''s that extra touch!</td>', 'I like the moving snow flakes, that''s that extra touch!', '2008-12-03 14:37:29.000000', NULL, 1),
(5102157, 743462, 39427, '<td valign="top">everything is EXCELLENT, meaning, technicals, etc, just the composition that seems a bit off balance - my eye doesn''t flow through the frame</td>', 'everything is EXCELLENT, meaning, technicals, etc, just the composition that seems a bit off balance - my eye doesn''t flow through the frame', '2008-12-03 14:38:53.000000', NULL, 1),
(5102160, 743490, 39427, '<td valign="top">nice colors, nice technicals, nice focus, etc, just seems like a rather "ordinary" shot for a "master''s" challenge... didn''t mean that to offend!  :D</td>', 'nice colors, nice technicals, nice focus, etc, just seems like a rather "ordinary" shot for a "master''s" challenge... didn''t mean that to offend!  :D', '2008-12-03 14:39:56.000000', NULL, 1),
