(5109350, 740915, 63398, '<td valign="top">Haunting &amp; evocative. Fav &amp; 9</td>', 'Haunting & evocative. Fav & 9', '2008-12-05 12:50:11.000000', NULL, 1),
(5109352, 743525, 63398, '<td valign="top">Subtly spectacular. 8</td>', 'Subtly spectacular. 8', '2008-12-05 12:50:43.000000', NULL, 1),
