(5113900, 743221, 32767, '<td valign="top">Beautiful girl and a nicely taken shot but I''m not getting much, in terms of personality from the expression. Good Luck</td>', 'Beautiful girl and a nicely taken shot but I''m not getting much, in terms of personality from the expression. Good Luck', '2008-12-07 12:44:47.000000', NULL, 1),
(5113903, 740891, 14211, '<td valign="top">she is beautiful</td>', 'she is beautiful', '2008-12-07 12:46:16.000000', NULL, 1),
(5113905, 743667, 32767, '<td valign="top">The blue tones are ethereal but I''m getting a bit distracted these days from what looks like some overburning in the sand. Good Luck!</td>', 'The blue tones are ethereal but I''m getting a bit distracted these days from what looks like some overburning in the sand. Good Luck!', '2008-12-07 12:47:20.000000', NULL, 1),
(5113910, 743544, 32767, '<td valign="top">I remember seeing a few scenes like this as I went to the outskirts of Central London. Wondering if it''s the same? Good Luck.</td>', 'I remember seeing a few scenes like this as I went to the outskirts of Central London. Wondering if it''s the same? Good Luck.', '2008-12-07 12:49:05.000000', NULL, 1),
(5113915, 740662, 32767, '<td valign="top">Commercial but it has a little edge. Pretty girls and smoke are always a winning combo. Maybe a cigar, nest time? Good Luck.</td>', 'Commercial but it has a little edge. Pretty girls and smoke are always a winning combo. Maybe a cigar, nest time? Good Luck.', '2008-12-07 12:51:18.000000', NULL, 1),
