(5114299, 738758, 40718, '<td valign="top">Ooh, I love the vivid greens.  A composition without obvious subject that works. 8</td>', 'Ooh, I love the vivid greens.  A composition without obvious subject that works. 8', '2008-12-07 16:34:03.000000', NULL, 1),
(5114300, 738279, 40718, '<td valign="top">Nice duotone.  I like the composition and sharpness. 8</td>', 'Nice duotone.  I like the composition and sharpness. 8', '2008-12-07 16:34:36.000000', NULL, 1),
(5114302, 739487, 40718, '<td valign="top">Tough subject.  Those branches oversharpen easily, which you avoided, but they look too soft here.  It''s a fine line. I think the composition of the tree lets us down a bit. 5</td>', 'Tough subject.  Those branches oversharpen easily, which you avoided, but they look too soft here.  It''s a fine line. I think the composition of the tree lets us down a bit. 5', '2008-12-07 16:35:34.000000', NULL, 1),
